set-variable.value:
@{
                    var query = context.Request.OriginalUrl.QueryString.TrimStart('?');
                    var retained = new System.Collections.Generic.List<string>();
                    var hasScope = false;
                    var hasResource = false;
                    foreach (var parameter in query.Split('&')) {
                        if (parameter.StartsWith("scope=", StringComparison.OrdinalIgnoreCase)) { hasScope = true; }
                        if (parameter.StartsWith("resource=", StringComparison.OrdinalIgnoreCase)) { hasResource = true; }
                        retained.Add(parameter);
                    }
                    if (!hasScope) { retained.Add("scope=https%3A%2F%2Fmcp.dev.azure.com%2F.default"); }
                    if (!hasResource) { retained.Add("resource=" + System.Uri.EscapeDataString("{{ado-remote-mcp-resource-url}}")); }
                    return retained.Count == 0 ? String.Empty : "?" + String.Join("&", retained);
                }

when.set-body:
@{
                    var form = context.Request.Body.As<string>(preserveContent: true);
                    var retained = new System.Collections.Generic.List<string>();
                    var hasScope = false;
                    var hasResource = false;
                    foreach (var parameter in form.Split('&')) {
                        if (parameter.StartsWith("scope=", StringComparison.OrdinalIgnoreCase)) { hasScope = true; }
                        if (parameter.StartsWith("resource=", StringComparison.OrdinalIgnoreCase)) { hasResource = true; }
                        retained.Add(parameter);
                    }
                    if (!hasScope) { retained.Add("scope=https%3A%2F%2Fmcp.dev.azure.com%2F.default"); }
                    if (!hasResource) { retained.Add("resource=" + System.Uri.EscapeDataString("{{ado-remote-mcp-resource-url}}")); }
                    return String.Join("&", retained);
                }
